/* A shared photographic piece lifts from the rail into an unboxed detail view. */
window.initShowroom=function({hero,nodes,focus,finishEntry,ease,onOpen,onClose}){
 const gs=window.gsap,reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const dialog=document.createElement('dialog');dialog.className='exhibit-dialog';dialog.setAttribute('aria-labelledby','exhibit-name');document.body.append(dialog);
 let origin=null,busy=false,closing=false,opening=false,returnFocus=null,scrollPosition=0;
 function completeClose(){dialog.close();hero.inert=false;hero.classList.remove('detail-open');origin?.classList.remove('is-detail-origin');document.documentElement.classList.remove('exhibit-open');closing=false;opening=false;onClose();returnFocus?.focus({preventScroll:true});window.scrollTo({top:scrollPosition,behavior:'instant'});origin=null;returnFocus=null;}
 function close(){if(!dialog.open||busy||closing)return;closing=true;gs?.killTweensOf(dialog.querySelectorAll('.exhibit-piece,.exhibit-info'));const preview=dialog.querySelector('.exhibit-piece'),photo=origin?.querySelector('.rail-rig');
  if(gs&&!reduced.matches&&photo){const from=preview.getBoundingClientRect(),to=photo.getBoundingClientRect();gs.to(dialog.querySelector('.exhibit-info'),{opacity:0,x:16,duration:.3});gs.to(preview,{x:to.x+to.width/2-from.x-from.width/2+(Number(gs.getProperty(preview,'x'))||0),y:to.y+to.height/2-from.y-from.height/2+(Number(gs.getProperty(preview,'y'))||0),scale:to.height/from.height*(Number(gs.getProperty(preview,'scale'))||1),duration:.75,ease:'power3.inOut',onComplete:completeClose});}else completeClose();
 }
 function open(product,node){if(dialog.open||closing)return;finishEntry();origin=node;returnFocus=document.activeElement;busy=false;closing=false;opening=true;scrollPosition=window.scrollY;const from=node.querySelector('.rail-rig').getBoundingClientRect();onOpen();
  dialog.innerHTML=`<button class="exhibit-close" type="button" aria-label="Back to clothing rail"><span aria-hidden="true">‹</span> Back to rail</button><div class="exhibit-stage"><div class="exhibit-piece" style="aspect-ratio:${product.imageWidth}/${product.imageHeight}"><img src="${product.views.front}" width="${product.imageWidth}" height="${product.imageHeight}" alt="${product.name} on a walnut hanger"></div></div><section class="exhibit-info"><span class="exhibit-eyebrow">SHADES / THE TAILORED EDIT</span><h2 id="exhibit-name">${product.name}</h2><p class="exhibit-description">${product.description}</p><p class="exhibit-price">${money(product.price)}</p><div class="exhibit-color"><i style="background:${product.swatch}" aria-hidden="true"></i><span>${product.color}</span></div><form id="exhibit-add"><fieldset><legend>SIZE</legend><div class="exhibit-sizes">${product.sizes.map(s=>`<label><input type="radio" name="size" value="${s}" required><span>${s}</span></label>`).join('')}</div></fieldset><button class="exhibit-add" type="submit"><span>ADD TO BAG</span></button><p class="exhibit-status" role="status"></p></form><details class="exhibit-material"><summary>Materials & care</summary><p>${product.fabric}. ${product.care}</p></details><a class="exhibit-bag" href="cart.html">View your bag</a><p class="exhibit-sample">Sample collection · No payment is taken.</p></section>`;
  dialog.showModal();hero.inert=true;document.documentElement.classList.add('exhibit-open');hero.classList.add('detail-open');origin.classList.add('is-detail-origin');dialog.scrollTop=0;
  const preview=dialog.querySelector('.exhibit-piece'),to=preview.getBoundingClientRect(),info=dialog.querySelector('.exhibit-info');
  if(gs&&!reduced.matches){gs.fromTo(preview,{x:from.x+from.width/2-to.x-to.width/2,y:from.y+from.height/2-to.y-to.height/2,scale:from.height/to.height},{x:0,y:0,scale:1,duration:1.1,ease,onComplete(){opening=false}});gs.fromTo(info,{x:22,opacity:0},{x:0,opacity:1,duration:.8,delay:.35,ease:'power3.out'});}else opening=false;
  dialog.querySelector('.exhibit-close').onclick=close;
  dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();if(busy)return;const size=new FormData(e.target).get('size');if(!product.sizes.includes(size))return;busy=true;dialog.setAttribute('aria-busy','true');const button=dialog.querySelector('.exhibit-add'),status=dialog.querySelector('.exhibit-status'),back=dialog.querySelector('.exhibit-close');button.disabled=true;back.disabled=true;button.innerHTML='<i class="exhibit-spinner" aria-hidden="true"></i><span>ADDING…</span>';status.textContent='Preparing your selection.';
   try{await window.addHeroToBag(product,size,preview);button.innerHTML='<span>ADDED</span>';status.innerHTML='Added to your bag. <a href="cart.html">View bag</a>';}catch{button.innerHTML='<span>ADD TO BAG</span>';status.textContent='Unable to add this piece. Please try again.';}finally{busy=false;button.disabled=false;back.disabled=false;dialog.removeAttribute('aria-busy');}
  };
 }
 dialog.addEventListener('cancel',e=>{e.preventDefault();close()});
 return {open,isOpen:()=>dialog.open};
};
